import difflib
events = []
class Item:
    def __init__(self, value):
        self.value = value
    def __hash__(self):
        return 1
    def __eq__(self, other):
        events.append('eq')
        return self.value == other.value
s = difflib.SequenceMatcher(lambda x: True, [Item(1)], [Item(1)])
events.clear()
print(tuple(s.find_longest_match()), events)

import difflib
events = []
class Truth:
    def __bool__(self):
        events.append('bool')
        return True
class Item:
    def __hash__(self):
        return 1
    def __eq__(self, other):
        events.append('eq')
        return Truth()
s = difflib.SequenceMatcher(lambda x: True, [Item()], [Item()])
events.clear()
print(tuple(s.find_longest_match()), events)

